import{_ as l,a0 as p,w as u,s as r,I as s,x as e,ao as a,a1 as o,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"详解在 Ubuntu 中引导到救援模式或紧急模式 | LCTT x X-CMD","titleTemplate":false,"description":"详解在 Ubuntu 中引导到救援模式或紧急模式 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"详解在 Ubuntu 中引导到救援模式或紧急模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"详解在 Ubuntu 中引导到救援模式或紧急模式 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220518 How To Boot Into Rescue Mode Or Emergency Mode In Ubuntu 22.04 - 20.04 - 18.04","title":"详解在 Ubuntu 中引导到救援模式或紧急模式","tag":"202206","desc":""},"relativePath":"202206/20220518 How To Boot Into Rescue Mode Or Emergency Mode In Ubuntu 22.04 - 20.04 - 18.04.md","filePath":"[post].md"}'),d={name:"202206/20220518 How To Boot Into Rescue Mode Or Emergency Mode In Ubuntu 22.04 - 20.04 - 18.04.md"};function c(h,t,b,g,k,m){const n=p("Link");return u(),r("div",null,[t[21]||(t[21]=s("h1",{id:"详解在-ubuntu-中引导到救援模式或紧急模式",tabindex:"-1"},[e("详解在 Ubuntu 中引导到救援模式或紧急模式 "),s("a",{class:"header-anchor",href:"#详解在-ubuntu-中引导到救援模式或紧急模式","aria-label":"Permalink to “详解在 Ubuntu 中引导到救援模式或紧急模式”"},"​")],-1)),t[22]||(t[22]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202206/14/153639n33fg3e2gc7xnvv3.jpg",alt:""})],-1)),t[23]||(t[23]=s("p",null,[e("这篇教程将介绍如何在 Ubuntu 22.04、20.04 和 18.04 LTS 版本中引导到 "),s("ruby",null,[e("救援"),s("rt",null,"Rescue")]),e(" 模式或 "),s("ruby",null,[e("紧急"),s("rt",null,"Emergency")]),e(" 模式。")],-1)),s("blockquote",null,[s("p",null,[t[1]||(t[1]=a("你可能已经知道，在 RHEL 7 、RHEL 8 、Ubuntu 16.04 LTS 及其更新的版本的 Linux 发行版中 <ruby>运行等级<rt>Runlevels</rt></ruby> 已经被 <ruby>系统目标<rt>Systemd target</rt></ruby> 所替代。更多关于 <ruby>运行等级<rt>Runlevel</rt></ruby> 和 <ruby>系统目标<rt>Systemd targets</rt></ruby> 的信息，参考 ",9)),o(n,{href:"https://ostechnix.com/check-runlevel-linux/"},{default:i(()=>[...t[0]||(t[0]=[e("这篇指南",-1)])]),_:1}),t[2]||(t[2]=e(" 。",-1))])]),t[24]||(t[24]=a('<p>这篇指南是针对 Ubuntu 编写的，但是，下面所给的步骤应该也适用于大多数使用 systemd 作为默认服务管理器的 Linux 发行版。</p><p>在进入主题前，让我们简单的理解：什么是 <ruby>救援<rt>rescue</rt></ruby> 模式 和 <ruby>紧急<rt>Emergency</rt></ruby> 模式，以及这两种模式的目的是什么。</p><h3 id="什么是救援模式" tabindex="-1">什么是救援模式？ <a class="header-anchor" href="#什么是救援模式" aria-label="Permalink to “什么是救援模式？”">​</a></h3><p>在 Linux 发行版中，救援模式等效于使用 SysV 作为默认的服务器管理器的 <ruby>单用户<rt>single user</rt></ruby> 模式。在救援模式中，将挂载所有的本地文件系统，将仅启动一些重要的服务。但是，不会启动一般的服务（例如，网络服务）。</p>',4)),s("p",null,[t[4]||(t[4]=e("救援模式在不能正常引导系统的情况下是很有用的。此外，我们可以在救援模式下执行一些重要的救援操作，例如，",-1)),o(n,{href:"https://ostechnix.com/how-to-reset-or-recover-root-user-password-in-linux/"},{default:i(()=>[...t[3]||(t[3]=[e("重新设置 root 密码",-1)])]),_:1}),t[5]||(t[5]=e(" 。",-1))]),t[25]||(t[25]=a('<h3 id="什么是紧急模式" tabindex="-1">什么是紧急模式？ <a class="header-anchor" href="#什么是紧急模式" aria-label="Permalink to “什么是紧急模式？”">​</a></h3><p>与救援模式相比，在紧急模式中，不会启动任何的东西。不会启动服务、不会挂载挂载点、不会建立套接字、什么都不会启动。你将所拥有的只是一个 <strong>原始的 shell</strong> 。紧急模式适用于调试目的。</p><p>首先，我们将看到如何在 Ubuntu 22.04 和 20.04 LTS 发行版中引导到救援模式或紧急模式。在 Ubuntu 22.04 和 20.04 LTS 中的过程是完全相同的！</p><h3 id="在-ubuntu-22-04-20-04-lts-中引导到救援模式" tabindex="-1">在 Ubuntu 22.04 / 20.04 LTS 中引导到救援模式 <a class="header-anchor" href="#在-ubuntu-22-04-20-04-lts-中引导到救援模式" aria-label="Permalink to “在 Ubuntu 22.04 / 20.04 LTS 中引导到救援模式”">​</a></h3><p>我们可以使用两种方法来引导到救援模式。</p><h4 id="方法-1" tabindex="-1">方法 1 <a class="header-anchor" href="#方法-1" aria-label="Permalink to “方法 1”">​</a></h4><p>打开你的 Ubuntu 系统。在 BIOS 徽标出现后，按下 <code>ESC</code> 按键来显示 GRUB 菜单。</p><p>在 GRUB 菜单中，选择第一项，并按下 <code>e</code> 按键来编辑它。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/GRUB-Menu-In-Ubuntu-22.04-LTS.png" alt="GRUB Menu In Ubuntu 22.04 / 20.04 LTS"></p><p>按下 <code>↓</code> 按键，并找到以单词 <code>linux</code> 开头的一行代码，并在其结尾处添加下面的一行代码。为到达其结尾处，只需要按下 <code>Ctrl + e</code> 组合键，或使用你键盘上的 <code>END</code> 按键或 <code>←</code>/<code>→</code> 按键。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemd.unit=rescue.target</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Edit-Grub-Boot-Menu-Entries-To-Enter-Into-Rescue-Mode-In-Ubuntu-22.04-LTS.png" alt="Edit Grub Boot Menu Entries To Enter Into Rescue Mode In Ubuntu 22.04 / 20.04 LTS"></p><p>在添加上面的代码行后，按下 <code>Ctrl + x</code> 组合键或按下 <code>F10</code> 按键来引导到救援模式。</p><p>数秒后，你将作为 root 用户来登录到救援模式（即单用户模式）。将会提示你按下回车键来进入维护。</p><p>下图是 Ubuntu 22.04 / 20.04 LTS 系统的救援模式的样子：</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Boot-Into-Rescue-Mode-In-Ubuntu-22.04.png" alt="Boot Into Rescue Mode In Ubuntu 22.04 / 20.04 LTS"></p><p>现在，在救援模式中做你想做的任何事。在救援模式中，在你执行任何操作前，你可能需要以 读/写模式来挂载根（<code>/</code>）文件系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -n -o remount,rw /</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Mount-Root-File-System-In-Read-Write-Mode-In-Ubuntu.png" alt="Mount Root File System In Read Write Mode In Ubuntu 22.04 / 20.04 LTS"></p><p>在完成后，按下 <code>Ctrl + d</code> 组合键来引导到正常模式。或者，你可以输入下面的任意一个命令来引导到正常模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl default</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><p>如果你想重新启动系统，而不是引导到正常的模式，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl reboot</span></span></code></pre></div><h4 id="方法-2" tabindex="-1">方法 2 <a class="header-anchor" href="#方法-2" aria-label="Permalink to “方法 2”">​</a></h4><p>在这种方法中，你不需要编辑 GRUB 启动菜单项目。</p><p>打开系统电源，并从 GRUB 启动菜单中选择 <ruby>Ubuntu 高级选项<rt>Advanced options for Ubuntu</rt></ruby>。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Choose-Advanced-Options-For-Ubuntu-From-Grub-Boot-Menu.png" alt="Choose Advanced Options For Ubuntu From Grub Boot Menu"></p><p>接下来，你将看到一个带有内核版本的可用的 Ubuntu 版本的列表。在 Ubuntu 中的 GRUB 启动菜单中选择 <ruby>恢复模式<rt>Recovery mode</rt></ruby> 。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Choose-Recovery-Mode-In-Grub-Boot-Menu-In-Ubuntu.png" alt="Choose Recovery Mode In Grub Boot Menu In Ubuntu 22.04 / 20.04 LTS"></p><p>数秒后，你将看到 Ubuntu 的 <ruby>恢复<rt>Recovery</rt></ruby> 菜单。从恢复菜单中，选择 <ruby>进入 root 的 shell 提示符<rt>Drop to root shell prompt</rt></ruby> 选项 ，并按下回车键。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Enter-Into-Root-Shell-Prompt-In-Ubuntu.png" alt="Enter Into Root Shell Prompt In Ubuntu 22.04 / 20.04 LTS"></p><p>现在，你将进入维护。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Ubuntu-Maintenance-Mode.png" alt="Ubuntu Maintenance Mode"></p><p>通过输入下面的命令来 以读/写模式的方式 来挂载根（<code>/</code>）文件系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -n -o remount,rw /</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Mount-Root-File-System-In-Read-Write-Mode-In-Ubuntu-1.png" alt="Mount Root File System In Read Write Mode In Ubuntu"></p><p>在救援模式中做你想做的任何事。</p><p>在完成后，输入 <code>exit</code> 来返回到恢复菜单。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><p>最后，选择 <ruby>救援正常启动<rt>Resume normal boot</rt></ruby> 选项，并按下回车键。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Boot-Into-Normal-Mode-In-Ubuntu.png" alt="Boot Into Normal Mode In Ubuntu"></p><p>再次按下回车键来退出恢复模式，并继续引导到正常模式。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Exit-The-Recovery-Mode-In-Ubuntu.png" alt="Exit The Recovery Mode In Ubuntu"></p><p>如果你不想引导到正常模式，从救援模式中输入 <code>reboot</code> 并按下回车键来重新启动你的系统。</p><h3 id="在-ubuntu-22-04-20-04-lts-中引导到紧急模式" tabindex="-1">在 Ubuntu 22.04 / 20.04 LTS 中引导到紧急模式 <a class="header-anchor" href="#在-ubuntu-22-04-20-04-lts-中引导到紧急模式" aria-label="Permalink to “在 Ubuntu 22.04 / 20.04 LTS 中引导到紧急模式”">​</a></h3><p>当 GRUB 菜单出现时，按下 <code>e</code> 按键来编辑它。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/GRUB-Menu-In-Ubuntu-22.04-LTS.png" alt="GRUB Menu In Ubuntu 22.04 / 20.04 LTS"></p><p>找到以单词 <code>linux</code> 开头的一行代码，并在其结尾处添加下面的一行代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemd.unit=emergency.target</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Edit-Grub-Boot-Menu-Entries-To-Enter-Into-Emergency-Mode-In-Ubuntu.png" alt="Edit Grub Boot Menu Entries To Enter Into Emergency Mode In Ubuntu 22.04 / 20.04 LTS"></p><p>在添加上面的代码行后，按下 <code>Ctrl + x</code> 组合键，或按下 <code>F10</code> 按键来引导到紧急模式。</p><p>数秒后，你将作为 <code>root</code> 用户来进入维护。将会提示你按下回车键来进入紧急模式。</p><p>下图是 Ubuntu 22.04 / 20.04 LTS 系统的紧急模式的样子：</p><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/Boot-Into-Emergency-Mode-In-Ubuntu-20.04-LTS.png" alt="Boot Into Emergency Mode In Ubuntu 22.04 / 20.04 LTS"></p><p>现在，在紧急模式中做你想做的任何事。在紧急模式中，在你执行任何操作前，你可能需要以读/写模式来挂载根（<code>/</code>）文件系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -n -o remount,rw /</span></span></code></pre></div><p>在完成后，按下 <code>Ctrl + d</code> 组合键来引导到正常模式。或者，你可以输入下面的任意一个命令来引导到正常模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl default</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><p>如果你想重新启动系统，而不是引导到正常模式，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl reboot</span></span></code></pre></div><h3 id="在-ubuntu-18-04-lts-中引导到救援模式" tabindex="-1">在 Ubuntu 18.04 LTS 中引导到救援模式 <a class="header-anchor" href="#在-ubuntu-18-04-lts-中引导到救援模式" aria-label="Permalink to “在 Ubuntu 18.04 LTS 中引导到救援模式”">​</a></h3><p>启动你的 Ubuntu 系统。当 GRUB 菜单出现时，选择第一项并按下按键 <code>e</code> 来编辑。（为到达其行尾处，只需要按下 <code>Ctrl + e</code> 组合键，或使用你键盘上的 <code>END</code> 按键或 <code>←</code>/<code>→</code> 按键）：</p><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/Grub-menu.png" alt="Grub Menu"></p><p>如果你没有看到 GRUB 菜单，只需要在 BIOS 徽标出现后，按下 <code>ESC</code> 按键来显示 GRUB 菜单。</p><p>找到以单词 <code>linux</code> 开头的一行代码，并在其结尾处添加下面的一行代码（为到达其行尾处，只需要按下 <code>Ctrl + e</code> 组合键，或使用你键盘上的 END<code>按键或</code>←<code>/</code>→` 按键）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemd.unit=rescue.target</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/Edit-grub-menu.png" alt="Edit Grub Menu"></p><p>在添加上面的代码行后，只需要按下 <code>Ctrl + x</code> 组合键，或按下 <code>F10</code> 按键来引导到救援模式。数秒后，你将作为 <code>root</code> 用户进入维护（即单用户模式）。</p><p>下图是 Ubuntu 18.04 LTS 服务器系统的救援模式的样子：</p><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/Ubuntu-rescue-mode.png" alt="Ubuntu Rescue Mode"></p><p>接下来，输入下面的命令来挂载根（<code>/</code>）文件系统为读/写模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -n -o remount,rw /</span></span></code></pre></div><h3 id="在-ubuntu-18-04-lts-中引导到紧急模式" tabindex="-1">在 Ubuntu 18.04 LTS 中引导到紧急模式 <a class="header-anchor" href="#在-ubuntu-18-04-lts-中引导到紧急模式" aria-label="Permalink to “在 Ubuntu 18.04 LTS 中引导到紧急模式”">​</a></h3><p>引导你的 Ubuntu 到紧急模式基本与上述方法相同。你所需要做的全部工作是，在编辑 GRUB 菜单时，将 <code>systemd.unit=rescue.target</code> 替换为 <code>systemd.unit=emergency.target</code> 。</p><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/emergency-mode.png" alt="Edit Grub Menu"></p><p>在你添加 <code>systemd.unit=emergency.target</code> 后，按下 <code>Ctrl + x</code> 组合键，或按下 <code>F10</code> 按键来引导到紧急模式。</p><p><img src="https://ostechnix.com/wp-content/uploads/2018/12/emergency-mode-1.png" alt="Ubuntu Emergency Mode"></p><p>最后，你可以使用下面的命令来以读/写模式的方式来挂载根（<code>/</code>）文件系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mount -n -o remount,rw /</span></span></code></pre></div><h3 id="在救援模式和紧急模式之间切换" tabindex="-1">在救援模式和紧急模式之间切换 <a class="header-anchor" href="#在救援模式和紧急模式之间切换" aria-label="Permalink to “在救援模式和紧急模式之间切换”">​</a></h3><p>如果你正在救援模式中，你不必像我上述提到的那样来编辑 GRUB 的菜单启动项。相反，你只想要输入下面的命令来立刻切换到紧急模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl emergency</span></span></code></pre></div><p>同样，为从紧急模式切换到救援模式，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl rescue</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>现在，你知道了什么是救援模式和紧急模式，以及如何在 Ubuntu 22.04 、20.04 和 18.04 LTS 系统中启动到这些模式。正如我已经提到的，在这里提供的这些步骤应该也适用于大多数当前使用 systemd 作为默认服务管理器的 Linux 发行版。</p><hr>',91)),s("p",null,[t[7]||(t[7]=e("via: ",-1)),o(n,{href:"https://ostechnix.com/how-to-boot-into-rescue-mode-or-emergency-mode-in-ubuntu-18-04/"},{default:i(()=>[...t[6]||(t[6]=[e("https://ostechnix.com/how-to-boot-into-rescue-mode-or-emergency-mode-in-ubuntu-18-04/",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=e("作者：",-1)),o(n,{href:"https://ostechnix.com/author/sk/"},{default:i(()=>[...t[8]||(t[8]=[e("sk",-1)])]),_:1}),t[13]||(t[13]=e(" 选题：",-1)),o(n,{href:"https://github.com/lkxed"},{default:i(()=>[...t[9]||(t[9]=[e("lkxed",-1)])]),_:1}),t[14]||(t[14]=e(" 译者：",-1)),o(n,{href:"https://github.com/robsean"},{default:i(()=>[...t[10]||(t[10]=[e("robsean",-1)])]),_:1}),t[15]||(t[15]=e(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[11]||(t[11]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[18]||(t[18]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原创编译，",-1)),o(n,{href:"https://linux.cn/"},{default:i(()=>[...t[17]||(t[17]=[e("Linux中国",-1)])]),_:1}),t[20]||(t[20]=e(" 荣誉推出",-1))])])}const U=l(d,[["render",c]]);export{x as __pageData,U as default};
